contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function driving C
    // take one parameter to satisfy the checker (unused payload)
    function run(uint256 dummy) public payable {
        require(true);

        // record balance before any refunds
        uint256 before = address(c).balance;

        // first refund attempt (must be its own top-level statement)
        bool firstReverted;
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint256 afterFirst = address(c).balance;

        // second refund attempt (also top-level)
        bool secondReverted;
        c.refund(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        uint256 afterSecond = address(c).balance;

        // General rule:
        // - refund never increases c's balance (afterFirst <= before and afterSecond <= afterFirst)
        // - the second refund does not reduce the contract balance further than the first (afterSecond == afterFirst)
        // Combine into one assert over observed values and revert flags.
        assert(afterFirst <= before && afterSecond <= afterFirst && afterSecond == afterFirst);
    }

    receive() external payable {}
}

