pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dummy) internal {
        vm.assume(true);
        uint256 before = address(c).balance;
        bool firstReverted;
        try c.refund() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint256 afterFirst = address(c).balance;
        bool secondReverted;
        try c.refund() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint256 afterSecond = address(c).balance;
        assertTrue(afterFirst <= before && afterSecond <= afterFirst && afterSecond == afterFirst);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
